<?php get_header(); ?><main id="main" class="wrap collection"><span class="eyebrow">OUR COLLECTION</span><h1>Bộ sưu tập sản phẩm</h1><p class="intro">Tìm cảm hứng mới cho nhịp sống của bạn.</p>
<form class="search" method="get" action="<?php echo esc_url(home_url('/')); ?>"><label for="product-search">Tìm sản phẩm</label><div><input id="product-search" name="s" placeholder="Tai nghe, bàn phím, đồng hồ…" value="<?php echo esc_attr(get_search_query()); ?>"><input type="hidden" name="post_type" value="product"><button class="button" type="submit">Tìm kiếm</button></div></form>
<div class="filters"><a href="<?php echo esc_url(get_post_type_archive_link('product')); ?>">Tất cả</a><?php $terms=get_terms(['taxonomy'=>'product_group','hide_empty'=>true]); if (!is_wp_error($terms)) { foreach ($terms as $term) { ?><a href="<?php echo esc_url(get_term_link($term)); ?>"><?php echo esc_html($term->name); ?></a><?php } } ?></div>
<div class="product-grid"><?php if (have_posts()) { while (have_posts()) { the_post(); techshow_card(); } } else { echo '<p>Chưa có sản phẩm phù hợp.</p>'; } ?></div><?php the_posts_pagination(); ?></main><?php get_footer(); ?>
